import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { processPaymentWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await processPaymentWorkflow(req.scope)
    .run({
      input: {
        action: "captured",
        data: {
          session_id: "payses_123",
          amount: 10
        }
      }
    })

  res.send(result)
}

